-- Hubnet receives only the short reference generated by hubnetReference().
-- Older checkout and provider-retry paths sometimes stored the full local
-- delivery_reference as provider_transaction_id when Hubnet returned no ID.
-- Normalize only those exact fallback rows so the saved ID matches the
-- reference that was sent to Hubnet.
update public.orders
set provider_transaction_id = left(delivery_reference, 12)
where delivery_provider = 'hubnet'
  and delivery_reference ~ '^DS[0-9A-Fa-f]{23}$'
  and provider_transaction_id = delivery_reference;
